import {createHash} from 'node:crypto';
import {dynamicAudioWaveform} from '../../server/dynamic-audio-routes.mjs';
import {dynamicMotionEnvironmentFromState,createSceneDynamicMotionDraft,previewSceneDynamicMotion} from '../../src/scene-dynamic-motion.mjs';
const hash=b=>createHash('sha256').update(b).digest('hex'),viewport={width:1920,height:1080},fps=30;
function wav(p){const h=Buffer.alloc(44);h.write('RIFF');h.writeUInt32LE(36+p.length,4);h.write('WAVE',8);h.write('fmt ',12);h.writeUInt32LE(16,16);h.writeUInt16LE(1,20);h.writeUInt16LE(1,22);h.writeUInt32LE(16000,24);h.writeUInt32LE(32000,28);h.writeUInt16LE(2,32);h.writeUInt16LE(16,34);h.write('data',36);h.writeUInt32LE(p.length,40);return Buffer.concat([h,p]);}
function evidence(takeId,src,sha256,startMs=500,endMs=3500){const pcm=Buffer.alloc(16000*10*2);for(let i=0;i<pcm.length/2;i++)pcm.writeInt16LE(Math.round(Math.sin(i*2*Math.PI/(src==='clips/original.mp4'?40:30))*3000),i*2);const payload={version:1,method:'pcm16-source-zero-waveform-v1',src,sha256,sourceClock:'source-zero-ms',clock:{basis:'first-video-pts',sourceOriginSec:0,audioFirstPtsSec:0,audioOffsetMs:0,audioStreamIndex:1,originalChannels:1},...dynamicAudioWaveform(pcm,{startMs,endMs,bins:32})},analysis={...payload,analysisSha256:hash(JSON.stringify(payload))},segment=pcm.subarray(startMs*32,endMs*32),bytes=wav(segment),playbackAsset={src:`derived-audio/${sha256}-${analysis.analysisSha256}.wav`,sha256:hash(bytes),kind:'audio',segmentPcmSha256:hash(segment),sourceSha256:sha256,analysisSha256:analysis.analysisSha256,sourceStartMs:startMs,sourceEndMs:endMs,sampleCount:segment.length/2,sampleRate:16000,channels:1,durationMs:endMs-startMs};return {takeId,sourceIdentity:{src,sha256,width:1920,height:1080,kind:'video',durationSec:40},analysis,playbackAsset};}
export function synthAudioFixture({sameSource=false,speed=1,duplicate=false}={}){
 const source={src:'clips/original.mp4',sha256:'a'.repeat(64),width:1920,height:1080,kind:'video',durationSec:40},raw={id:'s',src:source.src,clipId:'c',startMs:0,endMs:40000,layout:'cards',title:'合成声音比较',body:'只比较所选音频。',nodes:[{id:'a',text:'A原声'},{id:'b',text:'B原声'}]},clips=[{id:'c',src:source.src,inSec:0,outSec:40,speed}],audioEvidence=[evidence('A',source.src,source.sha256),evidence('B',sameSource?source.src:'broll-assets/other.mp4',sameSource?source.sha256:'b'.repeat(64),sameSource?4000:500,sameSource?7000:3500)];if(duplicate)clips.push({...clips[0],id:'d'});
 const state={clips,brollAssets:sameSource?[]:[{id:'b',src:'broll-assets/other.mp4',kind:'video'}],captions:[],brolls:[],music:null,accentColor:'#123456',presentation:{theme:'knowledge',format:'landscape',chapters:[],scenes:[raw]},meta:{fps,...viewport,durationInFrames:Math.round(40/speed*fps)*(duplicate?2:1)}};
 const config={kind:'audio-clock-ab',clock:'scene-source-relative-ms',binding:{sceneId:raw.id,src:source.src,sha256:source.sha256,startMs:0,endMs:40000},dataKind:'explicit-audio',provenance:'原创合成音频测试，不是语音准确率',audioOwner:{kind:'external-single-track',id:'owner'},order:'A-then-B',timeScaleMs:3000,copyWindow:{atMs:0,endMs:10000,rect:{x:.04,y:.04,width:.59,height:.76}},comparisonWindow:{atMs:10000,endMs:16000},takes:audioEvidence.map((e,i)=>({id:e.takeId,nodeId:i?'b':'a',expectedText:i?'B原声':'A原声',source:{src:e.sourceIdentity.src,sha256:e.sourceIdentity.sha256,analysisSha256:e.analysis.analysisSha256},startMs:e.analysis.range.startMs,endMs:e.analysis.range.endMs,playAtMs:i?13000:10000,labelRect:{x:.04,y:i?.5:.15,width:.59,height:.12},waveRect:{x:.04,y:i?.65:.3,width:.59,height:.08}}))};
 const env=dynamicMotionEnvironmentFromState(state,{sourceIdentity:source,audioEvidence,font:{status:'ready'}}),draft=createSceneDynamicMotionDraft(raw,config,env),saved={...raw,dynamicMotion:previewSceneDynamicMotion(draft)};state.presentation.scenes=[saved];return {source,raw,state,config,env,draft,saved,audioEvidence};
}

export function synthAudioBytes(e){const p=Buffer.alloc(16000*10*2);for(let i=0;i<p.length/2;i++)p.writeInt16LE(Math.round(Math.sin(i*2*Math.PI/(e.sourceIdentity.src==='clips/original.mp4'?40:30))*3000),i*2);return wav(p.subarray(e.analysis.range.startSample*2,e.analysis.range.endSample*2));}
